"""Next firing times of a five-field cron expression. See task.md."""

from __future__ import annotations

import calendar
import re
from datetime import datetime, timedelta
from typing import NamedTuple


class CronError(ValueError):
    """Raised for malformed expressions and for searches that find nothing."""


_MONTH_NAMES = {
    name: number
    for number, name in enumerate("JAN FEB MAR APR MAY JUN JUL AUG SEP OCT NOV DEC".split(), start=1)
}
_WEEKDAY_NAMES = {name: number for number, name in enumerate("SUN MON TUE WED THU FRI SAT".split())}
_NUMBER = re.compile(r"[0-9]+")
_SEARCH_YEARS = 5

_FIELDS = (
    ("minute", 0, 59, {}),
    ("hour", 0, 23, {}),
    ("day-of-month", 1, 31, {}),
    ("month", 1, 12, _MONTH_NAMES),
    ("day-of-week", 0, 7, _WEEKDAY_NAMES),
)


class _Schedule(NamedTuple):
    minutes: frozenset[int]
    hours: frozenset[int]
    days: frozenset[int]
    months: frozenset[int]
    weekdays: frozenset[int]
    day_restricted: bool
    weekday_restricted: bool


def _value(text: str, low: int, high: int, names: dict[str, int], field: str) -> int:
    number = names.get(text.upper())
    if number is None:
        if not _NUMBER.fullmatch(text):
            raise CronError(f"malformed {field} value {text!r}")
        number = int(text)
    if not low <= number <= high:
        raise CronError(f"{field} value {number} is outside {low}-{high}")
    return number


def _term(term: str, low: int, high: int, names: dict[str, int], field: str) -> range:
    base, slash, step_text = term.partition("/")
    step = 1
    if slash:
        if not _NUMBER.fullmatch(step_text):
            raise CronError(f"malformed step in {field} term {term!r}")
        step = int(step_text)
        if step < 1:
            raise CronError(f"step must be at least 1 in {field} term {term!r}")

    if base == "*":
        first, last = low, high
    elif "-" in base:
        low_text, _, high_text = base.partition("-")
        first = _value(low_text, low, high, names, field)
        last = _value(high_text, low, high, names, field)
        if first > last:
            raise CronError(f"range low bound above high bound in {field} term {term!r}")
    else:
        first = _value(base, low, high, names, field)
        last = high if slash else first
    return range(first, last + 1, step)


def _parse_field(text: str, low: int, high: int, names: dict[str, int], field: str) -> set[int]:
    values: set[int] = set()
    for term in text.split(","):
        values.update(_term(term, low, high, names, field))
    if field == "day-of-week":
        values = {value % 7 for value in values}
    return values


def _parse(expr: str) -> _Schedule:
    texts = expr.split()
    if len(texts) != 5:
        raise CronError(f"expected 5 fields, got {len(texts)} in {expr!r}")
    minutes, hours, days, months, weekdays = (
        frozenset(_parse_field(text, low, high, names, field))
        for text, (field, low, high, names) in zip(texts, _FIELDS)
    )
    return _Schedule(
        minutes=minutes,
        hours=hours,
        days=days,
        months=months,
        weekdays=weekdays,
        day_restricted=texts[2] != "*",
        weekday_restricted=texts[4] != "*",
    )


def _day_matches(moment: datetime, schedule: _Schedule) -> bool:
    day_ok = moment.day in schedule.days
    weekday_ok = moment.isoweekday() % 7 in schedule.weekdays
    if schedule.day_restricted and schedule.weekday_restricted:
        return day_ok or weekday_ok
    return day_ok and weekday_ok


def _next_match(moment: datetime, schedule: _Schedule, horizon: datetime) -> datetime | None:
    while moment <= horizon:
        if moment.month not in schedule.months:
            next_month = moment.year + (moment.month == 12), moment.month % 12 + 1
            moment = datetime(*next_month, 1)
        elif not _day_matches(moment, schedule):
            midnight = moment.replace(hour=0, minute=0)
            moment = midnight + timedelta(days=1)
        elif moment.hour not in schedule.hours:
            moment = moment.replace(minute=0) + timedelta(hours=1)
        elif moment.minute not in schedule.minutes:
            moment += timedelta(minutes=1)
        else:
            return moment
    return None


def _horizon(start: datetime) -> datetime:
    year = start.year + _SEARCH_YEARS
    day = min(start.day, calendar.monthrange(year, start.month)[1])
    return start.replace(year=year, day=day)


def next_firings(expr: str, start: datetime, count: int) -> list[datetime]:
    """Return the next `count` firing times strictly after `start`."""
    schedule = _parse(expr)
    if count <= 0:
        return []

    horizon = _horizon(start)
    results: list[datetime] = []
    candidate = start.replace(second=0, microsecond=0) + timedelta(minutes=1)
    while len(results) < count:
        firing = _next_match(candidate, schedule, horizon)
        if firing is None:
            raise CronError(f"no firing of {expr!r} within {_SEARCH_YEARS} years of {start}")
        results.append(firing)
        candidate = firing + timedelta(minutes=1)
    return results
